def _authorize_ticket(ticket: Ticket, user: User):
    if user.role == UserRole.customer_user:
        if ticket.organization_id != user.organization_id:
            raise HTTPException(status_code=403, detail="Not authorized to view this ticket")
    elif user.role == UserRole.support_agent:
        team_ids = [t.id for t in user.teams]
        if ticket.team_id and ticket.team_id not in team_ids:
            raise HTTPException(status_code=403, detail="Not authorized to view this ticket")

