def get_organization(org_id: int, db: Session = Depends(get_db), current_user: User = Depends(require_staff)):
    org = db.query(Organization).filter(Organization.id == org_id).first()
    if not org:
        raise HTTPException(status_code=404, detail="Organization not found")
    return org

def list_escalations(
    status: Optional[EscalationStatus] = Query(None),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_team_lead),
):
    query = db.query(Escalation).options(joinedload(Escalation.owner), joinedload(Escalation.ticket))
    if status:
        query = query.filter(Escalation.status == status)
    if current_user.role == UserRole.team_lead:
        team_ids = [t.id for t in current_user.teams]
        query = query.join(Ticket).filter(or_(Ticket.team_id.in_(team_ids), Ticket.team_id.is_(None)))
    escalations = query.order_by(Escalation.created_at.desc()).all()

def sla_dashboard(
    overdue_only: bool = Query(False),
    db: Session = Depends(get_db),
    current_user: User = Depends(require_staff),
):
    query = db.query(Ticket).options(joinedload(Ticket.assignee)).filter(
        Ticket.status.notin_([TicketStatus.resolved, TicketStatus.closed])
    )

if current_user.role != UserRole.customer_user:
        article_query = db.query(KBArticle).filter(
            or_(KBArticle.title.ilike(f"%{q}%"), KBArticle.content.ilike(f"%{q}%"))
        ).limit(10).all()
        articles = article_query

